head.script:
scwin.trigger1_onclick = function(e) {
    tabControl1.disableTab(1);
};
scwin.trigger2_onclick = function(e) {
    tabControl1.enableTab(1);
};
scwin.checkautoComplete1 = function() {
    return WebSquare.wUnit.getJq('#autoComplete1').hasClass('w2autoComplete_disabled');
}
scwin.checkselectbox1 = function() {
    return WebSquare.wUnit.getJq('#selectbox1').hasClass('w2selectbox_disabled');
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 'disable false'버튼을 클릭한다.-After executing the sample file, click the 'disable false' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 그리드안에 비활성화 되어있는 autocomplete, selectbox가 정상적으로 유지된다.(이전에는 enable로 풀림)- Autocomplete, selectbox disabled in grid (previously unlocked as enable)
    WebSquare.wUnit.addCommand("assert", "scwin.checkautoComplete1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkselectbox1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    tabControl1.setSelectedTabIndex(1);
    autoComplete1.setDisabled(true);
    //autoComplete1.setSelectedIndex(-1);
    selectbox1.setDisabled(true);
    //selectbox1.setSelectedIndex(-1);
    //Function unitTest
    //Create by Truong.Luu
    //Create date 18-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
